```bash
cat <<'EOF' > gen_wraparound_test.go
package main

import (
	"fmt"
	"github.com/VictoriaMetrics/fastcache"
)

func main() {
	// Create a small cache to force frequent wraparounds
	c := fastcache.New(1024)

	// Add and retrieve many entries to stress the generation wraparound
	for i := 0; i < 100000; i++ {
		key := fmt.Sprintf("key%d", i)
		value := fmt.Sprintf("value%d", i)

		c.Set([]byte(key), []byte(value))

		// Try to get the value back
		result := c.Get(nil, []byte(key))
		if string(result) != value {
			fmt.Printf("ERROR: Expected %s, got %s\n", value, string(result))
			return
		}
	}

	fmt.Println("Generation wraparound test passed!")
}
EOF
